from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel


class NetworkTokenActivationDataRequest(SdkBaseModel):
    sdk_output: Optional[str] = Field(default=UNSET, alias="sdkOutput")
    """A block of data automatically generated by Adyen's SDK for network token provisioning. This ``sdkOutput`` is
    required to create provisioning data for the network token.

    For more information, see the repositories for Adyen's SDKs for network token provisioning:
    * `Adyen Apple Pay Provisioning SDK <https://github.com/Adyen/adyen-apple-pay-provisioning-ios>`__.
    * `Adyen Google Wallet Provisioning SDK <https://github.com/Adyen/adyen-issuing-android>`__"""


class NetworkTokenActivationDataRequestDict(TypedDict):
    sdk_output: NotRequired[str]
